'use strict';
// The Firebase client module calls this bridge; null configuration preserves the existing demo.
window.KstoreCloud={enabled:!!window.KSTORE_FIREBASE,ready:false,catalogReady:false,auth:null,quote:null,publicListings:new Map(),ownedListings:new Map(),stores:new Map(),scheduleSave(){},applyCatalog(){}};
window.KstoreFirebaseUI={authMode:'signin',error:'',message:'',original:{home,login,summary,reviewStep,sellerOnboarding,sellerStore},
  authPage(){const ui=this,register=ui.authMode==='register',reset=ui.authMode==='reset';return '<section class="panel" style="max-width:460px;margin:40px auto"><div class="logo"><img src="assets/kstore-logo.png" alt="Kstore"></div><h1 class="page-title">'+(register?'Create your Kstore account':reset?'Reset your password':'Welcome back.')+'</h1><p class="muted small">Secure sign-in with Firebase.</p><form id="firebase-auth-form">'+(register?'<label class="field">Your name<input name="name" required maxlength="70" autocomplete="name"></label>':'')+'<label class="field">Email<input name="email" type="email" required autocomplete="email"></label>'+(!reset?'<label class="field">Password<input name="password" type="password" required minlength="8" autocomplete="'+(register?'new-password':'current-password')+'"></label>':'')+'<p class="error" role="alert">'+esc(ui.error)+'</p><p class="success" role="status">'+esc(ui.message)+'</p><button class="primary full">'+(register?'Create account':reset?'Send reset email':'Sign in')+'</button></form><div style="display:flex;gap:15px;margin-top:20px"><button class="text small" data-firebase-mode="'+(register||reset?'signin':'register')+'">'+(register||reset?'Sign in instead':'Create an account')+'</button>'+(!reset?'<button class="text small" data-firebase-mode="reset">Forgot password?</button>':'')+'</div></section>'},
  showError(error){this.error=error?.message||'The operation failed. Please retry.';toast(this.error)},
  catalogProduct(p){return {...p,stock:p.variants.reduce((n,v)=>n+Number(v.stock),0),image:p.images[0],gallery:p.images.map((src,i)=>({src,full:src,thumb:src,label:i===0?'Main image':'Image '+(i+1)})),variants:p.variants.map(v=>v.name),variantStock:Object.fromEntries(p.variants.map(v=>[v.name,v.stock])),unavailable:p.variants.filter(v=>v.stock===0).map(v=>v.name),listingStatus:p.status,rating:0,reviews:0,official:false,specs:{Description:p.description,Condition:p.condition,SKU:p.sku}}},
  loading(){if(KstoreCloud.fatal)return '<div class="panel empty"><h2>Account connection unavailable</h2><p class="error">'+esc(KstoreCloud.fatal)+'</p><button class="primary" data-firebase-action="retry">Retry</button> <button class="secondary" data-firebase-action="signout">Sign out</button></div>';return '<div class="panel empty"><h2>Connecting your account…</h2><p class="muted">Loading secure account and catalog data.</p></div>'}
};
const cloudOriginalHome=home;home=function(){if(!KstoreCloud.enabled)return cloudOriginalHome();return '<div class="home-top" style="display:block"><section class="hero"><div class="hero-copy"><span class="eyebrow">YOUR EVERYDAY, UPGRADED</span><h1>Good finds.<br><em>More possibilities.</em></h1><p>Discover products from Kstore sellers.</p><a class="primary" href="#/catalog">Explore the collection →</a></div></section></div><section class="section"><div class="section-head"><h2>Discover the marketplace</h2><a href="#/sell">Become a seller →</a></div>'+(products.filter(p=>p.listingStatus==='active').length?'<div class="product-grid">'+products.filter(p=>p.listingStatus==='active').slice(0,10).map(card).join('')+'</div>':'<div class="panel empty"><h2>New finds are on their way.</h2><p class="muted">Approved seller listings will appear here.</p><a class="primary" href="#/sell">Start selling</a></div>')+'</section>'};
const cloudOriginalLogin=login;login=function(){return KstoreCloud.enabled?KstoreFirebaseUI.authPage():cloudOriginalLogin()};
const cloudOriginalSync=syncSellerProducts;syncSellerProducts=function(){if(KstoreCloud.enabled)return KstoreCloud.applyCatalog();return cloudOriginalSync()};
const cloudOriginalOnboarding=sellerOnboarding;sellerOnboarding=function(){if(KstoreCloud.enabled&&!state.user)return login();if(KstoreCloud.enabled&&!KstoreCloud.auth?.emailVerified)return '<section class="panel empty"><h1>Verify your email to start selling.</h1><p class="muted">Check your inbox, then refresh verification status.</p><button class="primary" data-firebase-action="verify">Send verification email</button> <button class="secondary" data-firebase-action="refresh-auth">I have verified my email</button></section>';return cloudOriginalOnboarding()};
const cloudOriginalSummary=summary;summary=function(checkout=false){if(!KstoreCloud.enabled||!checkout)return cloudOriginalSummary(checkout);const q=KstoreCloud.quote;return '<div class="panel"><h3>Order summary</h3>'+(q?'<div class="summary-row"><span>Merchandise</span><b>'+money(q.subtotal)+'</b></div><div class="summary-row"><span>Delivery</span><b>'+money(q.shipping)+'</b></div><div class="summary-row"><span>Discount</span><b>−'+money(q.discount)+'</b></div><div class="summary-row total"><span>Total</span><b>'+money(q.total)+'</b></div>':'<p class="muted small">Choose delivery, then request your current server quote.</p>')+'</div>'};
const cloudOriginalReview=reviewStep;reviewStep=function(){if(!KstoreCloud.enabled)return cloudOriginalReview();return '<h2>Review your order</h2>'+state.cart.map(l=>'<div class="summary-row"><span>'+esc(getP(l.id)?.name||'Unavailable product')+' × '+l.qty+'</span><b>'+money((getP(l.id)?.price||0)*l.qty)+'</b></div>').join('')+'<p class="small">Payment: Pay on delivery. Online payments are not connected.</p><label class="small"><input id="accept-order" type="checkbox"> I confirm the delivery details and server-quoted total.</label><div class="spacer"></div><button class="primary full" data-action="place-order" '+(!KstoreCloud.quote?'disabled':'')+'>Place order'+(KstoreCloud.quote?' · '+money(KstoreCloud.quote.total):'')+'</button><p id="order-error" class="error" role="alert"></p>'};
const cloudOriginalStore=sellerStore;sellerStore=function(){if(!KstoreCloud.enabled)return cloudOriginalStore();const id=route().path.split('/')[3],s=KstoreCloud.stores.get(id);if(!s)return '<section class="panel empty"><h2>Store information unavailable</h2><p class="muted">This store may still be awaiting approval.</p></section>';const items=products.filter(p=>p.sellerId===id&&p.listingStatus==='active');return '<section class="panel section"><h1>'+esc(s.shopName)+'</h1><p>'+esc(s.description||'')+'</p><span class="status">Approved seller</span></section><div class="product-grid catalog-grid">'+items.map(card).join('')+'</div>'};
const cloudOriginalRender=render;render=function(){if(KstoreCloud.enabled&&(!KstoreCloud.ready||!KstoreCloud.catalogReady)){$('#app').innerHTML=header()+'<main class="wrap">'+KstoreFirebaseUI.loading()+'</main>';return}cloudOriginalRender();if(KstoreCloud.enabled){const copy={ 'Demo setup only. No identity verification or payout account is opened. Never enter bank account numbers or real identity documents here.':'Seller applications are saved securely. Publishing requires operator approval. Payouts are not connected; do not enter bank account numbers or identity documents here.', 'Use sample details for this browser-only demo.':'Your profile is saved to your Firebase account.', 'Your progress is saved in this browser after each step.':'Your application progress is saved to your account after each step.', 'Create demo store →':'Submit seller application →', 'Publish in demo catalog':'Publish after approval', 'Upload your first product':'Upload your first product', 'This interactive demo saves listings in this browser. Published listings appear in this browser’s catalog. A shared marketplace requires authenticated server storage.':'Seller profiles and listings are saved in Firebase. Approved active listings are shared across shoppers.', 'I understand this creates a browser-local demo store, not a verified seller account.':'I understand that publishing requires seller review and that payout setup is not connected.', 'Sample review · Demo content':'Illustrative review — not a customer purchase' };const walker=document.createTreeWalker($('main'),NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(copy[node.textContent.trim()])node.textContent=copy[node.textContent.trim()]}$('.demo-strip').textContent='Firebase connected · Online payments are not connected';$$('.seller-demo-note').forEach(e=>e.textContent='Firebase seller center · Listings are shared; publication requires approval.');$$('.status').forEach(e=>{if(/Demo store active/.test(e.textContent))e.textContent=state.seller?.verificationStatus==='approved'?'Approved seller':'Approval pending';});$$('.notice').forEach(e=>{if(e.textContent.includes('Demo checkout'))e.textContent='Your order uses server-validated prices and inventory. Online payments are not connected.'});if(state.user&&!KstoreCloud.auth?.emailVerified){const m=document.createElement('div');m.className='notice';m.innerHTML='Verify your email before selling or placing orders. <button class="text" data-firebase-action="verify">Send verification email</button> <button class="text" data-firebase-action="refresh-auth">Refresh status</button>';$('main').prepend(m)}}};

const cloudOriginalAccountContent=accountContent;accountContent=function(tab){if(KstoreCloud.enabled&&tab==='vouchers')return '<div class="panel"><h2>Your vouchers</h2><p class="muted">Only promotions configured by the operator can be applied at checkout.</p></div>';return cloudOriginalAccountContent(tab)};

if(!KstoreCloud.enabled)render();else{$('#app').innerHTML='<main class="wrap">'+KstoreFirebaseUI.loading()+'</main>'}

window.dispatchEvent(new Event("kstore-ui-ready"));
